const approvedAccountIds = new Set([
  '87bb0ffd-edb1-4c73-9e90-80e00a4cecc7',
  '1bbf09a1-fa5b-41de-8c3a-184d842fa59b',
  '161d9ebe-822c-4cc0-b730-1702318f5858',
  '8d746e56-ae78-4e90-8714-eed8b3e72a29',
  'e7359c77-7858-4bc6-be17-ebd3ffd4a4c9',
  'cca2cb66-9da8-4e7e-a70f-096d8b612bd5',
  '1b66c71c-3775-456b-9639-aafd7cf16c96',
]);

const transactions = [];
for (const item of $input.all()) {
  const body = item.json.body ?? item.json;
  const pageTransactions = body.BankTransactions ?? body.bankTransactions ?? [];
  if (Array.isArray(pageTransactions)) transactions.push(...pageTransactions);
}

const totals = {};
for (const tx of transactions) {
  const status = String(tx.Status ?? tx.status ?? '').toUpperCase();
  if (['DELETED', 'VOIDED'].includes(status)) continue;
  const bank = tx.BankAccount ?? tx.bankAccount ?? {};
  const accountId = bank.AccountID ?? bank.accountID ?? bank.id ?? '';
  if (!approvedAccountIds.has(accountId)) continue;
  const contact = tx.Contact ?? tx.contact ?? {};
  const contactName = String(contact.Name ?? contact.name ?? '').trim();
  if (!contactName) continue;
  let grossRevenue = 0;
  for (const line of (tx.LineItems ?? tx.lineItems ?? [])) {
    const code = Number(line.AccountCode ?? line.accountCode);
    const amount = Number(line.LineAmount ?? line.lineAmount ?? 0);
    if (code >= 4000 && code <= 4060 && amount > 0) grossRevenue += amount;
  }
  if (grossRevenue <= 0) continue;
  if (!totals[contactName]) totals[contactName] = { revenue: 0, count: 0 };
  totals[contactName].revenue += grossRevenue;
  totals[contactName].count += 1;
}
return [{ json: { totals, bankTransactionCount: transactions.length } }];

const paid = {};
const outstanding = {};
const invoices = [];
for (const item of $input.all()) {
  const body = item.json.body ?? item.json;
  const pageInvoices = body.Invoices ?? body.invoices ?? [];
  if (Array.isArray(pageInvoices)) invoices.push(...pageInvoices);
}
for (const invoice of invoices) {
  if (String(invoice.Type ?? invoice.type ?? '').toUpperCase() !== 'ACCREC') continue;
  const contact = invoice.Contact ?? invoice.contact ?? {};
  const name = String(contact.Name ?? contact.name ?? '').trim();
  if (!name) continue;
  const status = String(invoice.Status ?? invoice.status ?? '').toUpperCase();
  const paidAmount = Number(invoice.AmountPaid ?? invoice.amountPaid ?? 0);
  const dueAmount = Number(invoice.AmountDue ?? invoice.amountDue ?? 0);
  if (status === 'PAID' && paidAmount > 0) {
    if (!paid[name]) paid[name] = { revenue: 0, count: 0 };
    paid[name].revenue += paidAmount;
    paid[name].count += 1;
  }
  if (status === 'AUTHORISED' && dueAmount > 0) outstanding[name] = (outstanding[name] ?? 0) + dueAmount;
}
return [{ json: { paid, outstanding, invoiceCount: invoices.length } }];

const bank = $('Aggregate Xero Revenue').first().json.totals ?? {};
const invoices = $('Aggregate Xero Invoices').first().json;
const paidInvoices = invoices.paid ?? {};
const outstanding = invoices.outstanding ?? {};
const syncedAt = new Date().toISOString();

const normalize = value => String(value ?? '')
  .toLowerCase()
  .replace(/&/g, 'and')
  .replace(/[^a-z0-9]/g, '');

const aliases = {
  'marcelloincorporated': ['marcellosbordentown'],
  'fivensonstudiosllc': ['fivensonstudios'],
  'unleashedtechnologiesllc': ['unleashedtechnologies'],
  'awingvisualsinc': ['awingvisuals'],
  'snowballprintmarketinginc': ['snowballprintmarketing'],
  'forevercardholdings': ['forevercard'],
  'mcintyredigital': ['mcintyredigital', 'mitchmcintyre'],
};

const bankIndex = {};
for (const [name, value] of Object.entries(bank)) bankIndex[normalize(name)] = value;
const invoiceIndex = {};
for (const [name, value] of Object.entries(paidInvoices)) invoiceIndex[normalize(name)] = value;
const dueIndex = {};
for (const [name, value] of Object.entries(outstanding)) dueIndex[normalize(name)] = value;

const updates = [];
const exceptions = [];
for (const item of $input.all()) {
  const row = item.json;
  const clientName = row.Name ?? row.name ?? '';
  const keys = [normalize(clientName), ...(aliases[normalize(clientName)] ?? [])];
  const bankMatches = keys.map(k => bankIndex[k]).filter(Boolean);
  const invoiceMatches = keys.map(k => invoiceIndex[k]).filter(Boolean);
  const due = keys.reduce((sum, k) => sum + Number(dueIndex[k] ?? 0), 0);

  let revenue = 0;
  let count = 0;
  let source = '';
  if (bankMatches.length) {
    revenue = bankMatches.reduce((sum, v) => sum + Number(v.revenue ?? 0), 0);
    count = bankMatches.reduce((sum, v) => sum + Number(v.count ?? 0), 0);
    source = 'Xero matched client/company sales transactions';
  } else if (invoiceMatches.length) {
    revenue = invoiceMatches.reduce((sum, v) => sum + Number(v.revenue ?? 0), 0);
    count = invoiceMatches.reduce((sum, v) => sum + Number(v.count ?? 0), 0);
    source = 'Xero paid invoices (fallback)';
  }

  if (!revenue) {
    exceptions.push({ airtableRecordId: row.id, clientName, reason: 'No confident Xero client/company match' });
    continue;
  }
  updates.push({
    airtableRecordId: row.id,
    clientName,
    actualLifetimeRevenue: Math.round(revenue * 100) / 100,
    transactionCount: count,
    outstandingReceivables: Math.round(due * 100) / 100,
    revenueSource: source,
    syncedAt
  });
}

return [{ json: { updates, exceptions, matchedCount: updates.length, exceptionCount: exceptions.length, syncedAt } }];

const result = $('Match Clients and Prepare Updates').first().json;
return [{ json: {
  status: result.exceptionCount ? 'completed_with_exceptions' : 'completed',
  matchedClients: result.matchedCount,
  unmatchedClients: result.exceptionCount,
  exceptions: result.exceptions,
  syncedAt: result.syncedAt,
  note: result.exceptionCount ? 'Review exceptions and add aliases only after confirming the Xero customer identity.' : 'All paying clients matched.'
} }];
